// CIDR to netmask, for special
function nmfc(b) {var m=[];for(var i=0;i<4;i++) {var n=Math.min(b,8); m.push(256-Math.pow(2, 8-n)); b-=n;} return m.join('.');}
// replace repeating sequences in domain
function patternreplace(s, lzpmask) {
  var patterns = {'!A': 'porn', '!B': 'film', '!C': 'lord', '!D': 'kino', '!E': 'oker', '!F': 'trad', '!G': 'game', '!H': 'line', '!I': '.com', '!J': 'pdom', '!K': 'tion', '!L': 'leon', '!M': 'port', '!N': 'shop', '!O': 'club', '!P': 'mark', '!Q': 'prav', '!R': 'eria', '!S': 'slot', '!T': 'vest', '!U': 'play', '!V': 'ital', '!W': 'tube', '!X': 'inco', '!Y': 'vide', '!Z': 'russ', '!@': 'star', '!#': 'ster', '!$': 'scho', '!%': 'enta', '!^': 'free', '!&': 'nter', '!*': 'gama', '!(': 'medi', '!)': 'mega', '!=': 'best', '!+': 'kra3', '!/': 'stor', '!,': 'ture', '!<': 'seed', '!>': 'pics', '!~': 'prof', '![': 'tech', '!]': 'news', '!{': 'ance', '!}': 'info', '!`': 'rypt', '!:': 'coin', '!;': 'teen', '!?': 'site', 'A': 'in', 'B': 'an', 'C': 'er', 'D': 'ar', 'E': 'or', 'F': 'et', 'G': 'st', 'H': 'al', 'I': 'on', 'J': 'en', 'K': 'ro', 'L': 'at', 'M': 'es', 'N': 'as', 'O': 'el', 'P': 'it', 'Q': 'am', 'R': 'ch', 'S': 'ol', 'T': 'om', 'U': 'ra', 'V': 'ex', 'W': 'is', 'X': 're', 'Y': 'os', 'Z': 'ic', '@': 'ka', '#': 'us', '$': 'ot', '%': 'im', '^': 'ov', '&': 'ap', '*': 'ad', '(': '-s', ')': 'il', '=': 'em', '+': 'ed', '/': 'op', ',': 'od', '<': 'a-', '>': 'ir', '~': 'id', '[': 'ig', ']': 'ob', '{': 'ag', '}': 'iv', '`': 'le', ':': 'un', ';': 'ur', '?': 'ok'};
  if (lzpmask)
   var patterns = {'AA': '!', 'AB': '@', 'gA': '#', 'CA': '$', 'EA': '%', 'IA': '^', 'QA': '*', 'BA': '(', 'wA': ')', 'AE': '[', 'AQ': ']', 'AI': '-', 'AC': ',', 'Ag': '.', 'Bg': '?'};
  for (pattern in patterns) {
    s = s.split(patterns[pattern]).join(pattern);
  }
  return s;
}
